// Trying to hack together a neat visualizer I saw a year or so ago,
// something along those lines...

// optimizations? better camera movement?

const int MAX_MARCH_STEPS = 20;
const float EPSILON = .001;
const float PI = 3.14159;
const float PI23 = PI * .66;
const float LIGHT_INTENSITY =  .8;
const float BASE_LIGHT = 0.7;

struct Light
{
    vec3 Position;
    vec3 Color;
};


struct Ray
{
    vec3 Origin;
    vec3 Direction;
};

struct Camera
{
    vec3 Position;
    vec3 LookAt;
    vec3 Up;
};

mat4 ViewMatrix(Camera camera)
{
    vec3 viewDir = normalize(camera.LookAt - camera.Position);
    vec3 right = normalize(cross(viewDir, camera.Up));
    vec3 transUp = normalize(cross(right, viewDir));

    return mat4(
        vec4(right, 0.0),
        vec4(transUp, 0.0),
        vec4(-viewDir, 0.0),
        vec4(0.0, 0.0, 0.0, 1.0)
    );
}

//Almost all of the SDF functions are taken directly from or adapted from:
//https://iquilezles.org/articles/distfunctions
float IntersectSDF(float distA, float distB) 
{
    return max(distA, distB);
}

float UnionSDF(float distA, float distB) 
{
    return min(distA, distB);
}

float DifferenceSDF(float distA, float distB) 
{
    return max(distA, -distB);
}

float SphereSDF(vec3 center, float radius)
{
    return length(center) - radius;
}

float BoxSDF(vec3 p, vec3 b)
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

// Create infinite copies of an object
vec3 opRep( in vec3 p, in vec3 c)
{
    vec3 q = mod(p+0.5*c,c)-0.5*c;
    return q;
}

//A single instance of the infinitely repeated scene
float RepeatedSceneSingleInstance(vec3 point)
{
    float finalT = 10.;
    float i_step = 1./20.;
    float i = -2.5;
    for(int j=0; j<125; j++)
    {
        float freq = texture(iChannel0, vec2((i + 2.5) / 20.0, 0.0)).x;
        float discFrequency = pow(floor(freq * 20.0) / 20.0, 4.0) * 4.0;

        vec3 boxPoint = vec3(5.-point.x-10.*sin(i), 5.-point.y, point.z-10.*cos(i));
        finalT = UnionSDF(finalT, BoxSDF(boxPoint, vec3(.1, discFrequency,.1)));
        i += i_step;
    }


    return finalT;
}


//The single instance scene
float NormalScene(vec3 point, Light light1, Light light2, Light light3)
{
    vec3 lightPoint = point - light1.Position;
    float t = SphereSDF(lightPoint, .5);

    lightPoint = point - light2.Position;
    t = UnionSDF(t, SphereSDF(lightPoint, .5));

    lightPoint = point - light3.Position;
    t = UnionSDF(t, SphereSDF(lightPoint, .5));
    return t;
}


vec3 GetNormal(vec3 point, Light light1, Light light2, Light light3) 
{
    vec3 normal = vec3(0,0,0);

    normal.x  = RepeatedSceneSingleInstance(vec3(point.x + EPSILON, point.y, point.z));
    normal.x -= RepeatedSceneSingleInstance(vec3(point.x - EPSILON, point.y, point.z));

    normal.y  = RepeatedSceneSingleInstance(vec3(point.x, point.y + EPSILON, point.z));
    normal.y -= RepeatedSceneSingleInstance(vec3(point.x, point.y - EPSILON, point.z));

    normal.z  = RepeatedSceneSingleInstance(vec3(point.x, point.y, point.z + EPSILON));
    normal.z -= RepeatedSceneSingleInstance(vec3(point.x, point.y, point.z - EPSILON));

    return normalize(normal);
}

float RayMarch(Ray ray, float startingTValue, float maxTValue) 
{
    float currentT = startingTValue;

    for(int i = 0; i < MAX_MARCH_STEPS; ++i) 
    {
        vec3 point = ray.Origin + ray.Direction * currentT;

        float closestTValue = RepeatedSceneSingleInstance(point);
        currentT += closestTValue;

        if(closestTValue < EPSILON || closestTValue > maxTValue) 
        {
            return currentT;
        }
    }

    return currentT;
}

float RayMarchLights(Ray ray, float startingTValue, float maxTValue, Light light1, Light light2, Light light3) 
{
    float currentT = startingTValue;

    for(int i = 0; i < MAX_MARCH_STEPS; ++i) 
    {
        vec3 point = ray.Origin + ray.Direction * currentT;

        float closestTValue = NormalScene(point, light1, light2, light3);
        currentT += closestTValue;

        if(closestTValue < EPSILON || closestTValue > maxTValue) 
        {
            return currentT;
        }
    }

    return currentT;
}


float Diffuse(vec3 point, vec3 normal, Light light) 
{

    vec3 lightVector = normalize(light.Position - point);

    float cosAngle = max(dot(lightVector, normal), 0.0);

    return max(cosAngle, 0.0);
}

float Specular(vec3 point, vec3 normal, Camera camera, Light light, float shinyNess) 
{
    vec3 lightVector = normalize(light.Position - point);
    lightVector = reflect(lightVector, normal);
    vec3 viewVector = normalize(camera.Position - point);

    float cosAngle = pow(max(dot(-lightVector, viewVector), 0.0), shinyNess);

    return max(cosAngle, 0.0);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord)
{
    //Generating our ray
    vec2 uvRay = (fragCoord - .5 * iResolution.xy) / iResolution.y;


    vec3 col = vec3(0,0,0);

    //Construct camera
    Camera camera;
    camera.Position = vec3(cos(iTime * .25) * 0.0, 10, sin(iTime * .25) * 20.0);
    camera.Up = vec3(0, 1, 0);
    camera.LookAt = vec3(10, 2, 0);

    mat4 worldToView = ViewMatrix(camera);

    vec4 worldDirection = normalize(vec4(uvRay, -1, 0));
    vec4 viewDir = worldToView * worldDirection;

    //Get view ray
    Ray ray;
    ray.Origin = camera.Position;
    ray.Direction = viewDir.xyz;

    vec4 tx = vec4(texture(iChannel0, uvRay));
    vec3 k = 0.9*cos(tx.x*8.9)*cos(tx.x*8.9)*vec3(0.15, 0.25, 0.55) ;

    float bassFreq = texture(iChannel0, vec2((.1), 0.0)).x;
    float medFreq = texture(iChannel0, vec2((.2), 0.0)).x;
    medFreq += texture(iChannel0, vec2((.3), 0.0)).x;
    medFreq += texture(iChannel0, vec2((.4), 0.0)).x;
    medFreq = medFreq / 3.0;

    float topFreq = texture(iChannel0, vec2((.5), 0.0)).x;
    topFreq += texture(iChannel0, vec2((.6), 0.0)).x;
    topFreq += texture(iChannel0, vec2((.7), 0.0)).x;
    topFreq += texture(iChannel0, vec2((.8), 0.0)).x;
    topFreq += texture(iChannel0, vec2((.9), 0.0)).x;
    topFreq = topFreq / 5.0f;

    vec3 lightColor = vec3(1, 0.533, 0.066);

    //Define our lights
    Light light1;
    light1.Position = camera.LookAt + vec3(cos(iTime * 1.0), .25, sin(iTime * 1.0)) * 10.0;
    light1.Color = BASE_LIGHT * lightColor;
    vec3 light1ModulatedColor = BASE_LIGHT * lightColor + lightColor * LIGHT_INTENSITY * bassFreq;

    lightColor = vec3(0.125, 0.639, 0.619);
    Light light2;
    light2.Position = camera.LookAt + vec3(cos(PI23 + iTime * 1.0), .25, sin(PI23 + iTime * 1.0)) * 10.0;
    light2.Color = BASE_LIGHT * lightColor;
    vec3 light2ModulatedColor = BASE_LIGHT * lightColor + lightColor * LIGHT_INTENSITY * medFreq;

    lightColor = vec3(0.615, 0, 1);
    Light light3;
    light3.Position = camera.LookAt + vec3(cos(2.0 * PI23 + iTime * 1.0), .25, sin(2.0 * PI23 + iTime * 1.0)) * 10.0;
    light3.Color = BASE_LIGHT * lightColor;
    vec3 light3ModulatedColor = BASE_LIGHT * lightColor + lightColor * LIGHT_INTENSITY * topFreq;

    float rayTValue = RayMarch(ray, 0.0, 100.0);

    vec3 point = ray.Origin + ray.Direction * rayTValue;
    float closestTValue = RepeatedSceneSingleInstance(point);

    if(closestTValue < EPSILON) 
    {
        vec3 surfaceColor = vec3(1.0f, 1.0f, 1.0f);
        vec3 normal = GetNormal(point, light1, light2, light3);
        col = surfaceColor * .1f;  

        col += Diffuse(point, normal, light1) * light1ModulatedColor * surfaceColor;
            col += Specular(point, normal, camera, light1, 10.0) * light1ModulatedColor * surfaceColor;
        col += Diffuse(point, normal, light2) * light2ModulatedColor * surfaceColor;
          col += Specular(point, normal, camera, light2, 10.0) * light2ModulatedColor * surfaceColor;
        col += Diffuse(point, normal, light3) * light3ModulatedColor * surfaceColor;
        col += Specular(point, normal, camera, light3, 10.0) * light3ModulatedColor * surfaceColor;
    }
   //  col = clamp(pow(vec3(col*bassFreq),0.3/col), vec3(0),vec3(2));

 //  col = mix(col, vec3(0,0,0), min(rayTValue / 200.0, 1.0));

    fragColor = vec4(col, rayTValue);
}

vec3 B2_spline(vec3 x) { // returns 3 B-spline functions of degree 2
    vec3 t = 3.0 * x;
    vec3 b0 = step(0.0, t)     * step(0.0, 1.0-t);
	vec3 b1 = step(0.0, t-1.0) * step(0.0, 2.0-t);
	vec3 b2 = step(0.0, t-2.0) * step(0.0, 3.0-t);
	return 0.5 * (
    	b0 * pow(t, vec3(2.0)) +
    	b1 * (-2.0*pow(t, vec3(2.0)) + 6.0*t - 3.0) + 
    	b2 * pow(3.0-t,vec3(2.0))
    );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // create pixel coordinates
	vec2 uv = fragCoord.xy / iResolution.xy;

    float fVBars = 100.;
    float fHSpacing = 1.00;


    float x = floor(uv.x * fVBars)/fVBars;
    float fSample = texture( iChannel0, vec2(abs(2.0 * x - 1.0), 0.25)).x;


	float fft = 1.0 * fSample* 0.5;

    float fHBars = 100.0;
    float fVSpacing = 0.180;
    float fVFreq = (uv.y * 3.14);


    vec2 centered = vec2(1.0) * uv - vec2(1.0);
    float t = iTime / 100.0;
    float polychrome = 1.0;
    vec3 spline_args = fract(vec3(polychrome*uv.x-t) + vec3(0.0, -1.0/3.0, -2.0/3.0));
    vec3 spline = B2_spline(spline_args);

    float f = abs(centered.y);
    vec3 base_color  = vec3(1.0, 1.0, 1.0) - f*spline;
    vec3 flame_color = pow(base_color, vec3(3.0));

    float tt = 0.3 - uv.y;
    float df = sign(tt);
    df = (df + 1.0)/0.5;
    vec3 col = flame_color * vec3(1.0 - step(fft, abs(0.3-uv.y))) * vec3(fVFreq);
    col -= col * df * 0.180;

	// output final color
	fragColor = vec4(col,1.0);
}

/*
    "Accretion" by @XorDev

    I discovered an interesting refraction effect
    by adding the raymarch iterator to the turbulence!
    https://x.com/XorDev/status/1936884244128661986
*/

void mainImage(out vec4 O, vec2 I)
{
    //Raymarch depth
    float z,
    //Step distance
    d,
    //Raymarch iterator
    i;
    //Clear fragColor and raymarch 20 steps
    for(O*=i; i++<2e1; )
    {
        //Sample point (from ray direction)
        vec3 p = z*normalize(vec3(I+I,0)-iResolution.xyx)+.1;

        //Polar coordinates and additional transformations
        p = vec3(atan(p.y/.2,p.x)*2., p.z/3., length(p.xy)-5.-z*.2);

        //Apply turbulence and refraction effect
        for(d=0.; d++<7.;)
            p += sin(p.yzx*d+iTime+.3*i)/d;

        //Distance to cylinder and waves with refraction
        z += d = length(vec4(.4*cos(p)-.4, p.z));

        //Coloring and brightness
        O += (1.+cos(p.x+i*.4+z+vec4(6,1,2,0)))/d;
    }
    //Tanh tonemap
    O = tanh(O*O/4e2);
}

float fns(float n, float nt){
    return (sin(n+nt)*.5+.5);
}
float f_n(
    vec2 o_trn, 
    float n_its, 
    float n_t,
    float n_scl_min
){

    float n_tau = radians(360.);
    float n_min = 1.;
    float n_col = 1.;
    float n_dcntr = length(o_trn);
    n_t+=n_dcntr;
    for(float n_it = 0.; n_it < n_its; n_it+=1.){

        float n_it_nor = n_it / n_its;
        float noff = 0.;
        float n_amp = 0.5;//(sin(iTime)*.5+.5)*.2;
        vec2 o = vec2(
            sin((n_it_nor)*n_tau), 
            cos((n_it_nor)*n_tau)
        )*n_amp-o_trn;

        float n = max(abs(o.x), abs(o.y));
        float nc = length(o);
        float t1 = fns(0., n_t+n_dcntr*18.);
        n = t1 * nc + (1.-t1)*n;
        //n = sin(n*33.*(1./nc))*.5+.5;
        //n = sin(n*22.*(1./nc))*.5+.5;

        n = sin(n*52.*pow(n, fns(0.,n_t)*.2)+n_t)*.5+.5;
        n = pow(n, 1./(fns(n_dcntr,n_t)*20.));

        float n_res = n;


        n_col*=n_res;
    }

    n_col = clamp(n_col, 0., 1.);


    return n_col; 
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    float n_scl_min = min(iResolution.x, iResolution.y);
    vec2 o_trn = (fragCoord.xy-iResolution.xy*.5)/n_scl_min;
    float nt = iTime*2.;
    vec3 o_col = vec3(
        1.-f_n(o_trn, 4., nt+0.1, n_scl_min),
        1.-f_n(o_trn, 4., nt+0.2, n_scl_min),
        1.-f_n(o_trn, 4., nt+0.3, n_scl_min)
    );
    fragColor = vec4(o_col, 1.);
}

//
// Chromatic Resonance by Philippe Desgranges
// Email: Philippe.desgranges@gmail.com
// License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License.
//

#define MUSIC_REACTION 0.2

#define S(a, b, c) smoothstep(a, b, c)
#define sat(a) clamp(a, 0.0, 1.0)

#define pi 3.14159265359
#define pi2 (pi * 2.0)
#define halfPi (pi * 0.5)


// Some hash function 2->1
float N2(vec2 p)
{	// Dave Hoskins - https://www.shadertoy.com/view/4djSRW
    p = mod(p, vec2(1456.2346));
	vec3 p3  = fract(vec3(p.xyx) * vec3(443.897, 441.423, 437.195));
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.x + p3.y) * p3.z);
}


float CosineInterpolate(float y1, float y2, float t)
{
   float mu = (1.0 -cos(t * pi)) * 0.5;
   return (y1 * (1.0 - mu) + y2 * mu);
}

// A 2d Noise (Cosine interpolation is more plasing for this effect)
float Noise2(vec2 uv)
{
    vec2 corner = floor(uv);
	float c00 = N2(corner + vec2(0.0, 0.0));
	float c01 = N2(corner + vec2(0.0, 1.0));
	float c11 = N2(corner + vec2(1.0, 1.0));
	float c10 = N2(corner + vec2(1.0, 0.0));

    vec2 diff = fract(uv);

    return CosineInterpolate(CosineInterpolate(c00, c10, diff.x), CosineInterpolate(c01, c11, diff.x), diff.y);
}

float LineNoise(float x, float t)
{
    float n = Noise2(vec2(x * 0.6, t * 0.2));
    //n += Noise2(vec2(x * 0.8, t * 0.2 + 34.8)) * 0.5;
    //n += Noise2(vec2(x * 1.2, t * 0.3 + 56.8)) * 0.25;

    return n - (1.0) * 0.5;
}


float line(vec2 uv, float t, float scroll)
{

    float ax = abs(uv.x);
    uv.y *= 0.5 + ax * ax * 0.3; 


    uv.x += iTime * scroll;

    float n1 = LineNoise(uv.x, t);


    float n2 = LineNoise(uv.x + 0.5, t + 10.0) * 2.0;

    float ay = abs(uv.y - n1);
    float lum = S(0.02, 0.00, ay) * 1.5;
    lum += S(1.5, 0.00, ay) * 0.1;


    float r = (uv.y - n1) / (n2 - n1);
    float h = sat(1.0 - r);
    if (r > 0.0) lum = max(lum, h * h * 0.7);

    return lum;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (2.0*fragCoord-iResolution.xy)/iResolution.y;


    float xWave = fragCoord.x / iResolution.x;

    float wave = texture(iChannel0, vec2(xWave * 0.2, 1.0)).r * sin(iTime * 0.2 ) * MUSIC_REACTION;
    float wave1 = texture(iChannel0, vec2(xWave * 0.2 + 0.2, 1.0)).r * sin(iTime * 0.2 + 0.5) * MUSIC_REACTION;
    float wave2 = texture(iChannel0, vec2(xWave * 0.2 + 0.4, 1.0)).r * sin(iTime * 0.2 + 1.0) * MUSIC_REACTION;
    float wave3 = texture(iChannel0, vec2(xWave * 0.2 + 0.6, 1.0)).r * sin(iTime * 0.2 + 1.5) * MUSIC_REACTION;
    float wave4 = texture(iChannel0, vec2(xWave * 0.2 + 0.8, 1.0)).r * sin(iTime * 0.2 + 2.0) * MUSIC_REACTION;

  //  fragColor = vec4(lum, lum, lum, 1.0); return;


    float lum = line(uv * vec2(2.0, 1.0)+  vec2(0.0, wave), iTime * 0.3, 0.1) * 0.6;
    lum += line(uv * vec2(1.5, 0.9) +  vec2(0.33, wave1), iTime * 0.5 + 45.0, 0.15) * 0.5;
    lum += line(uv * vec2(1.3, 1.2) +  vec2(0.66, wave2), iTime * 0.4 + 67.3, 0.2) * 0.3;
    lum += line(uv * vec2(1.5, 1.15) +  vec2(0.8, wave3), iTime * 0.77 + 1235.45, 0.23) * 0.43;
    lum += line(uv * vec2(1.5, 1.15) +  vec2(0.8, wave4), iTime * 0.77 + 456.45, 0.3) * 0.25;


    float ax = abs(uv.x);

    lum += ax * ax * 0.05;


    vec3 col;

    float x = uv.x * 1.2 + iTime * 0.2;

    vec3 hue = (sin(vec3(x, x + pi2 * 0.33, x + pi2 * 0.66)) + vec3(1.0)) * 0.7;


    // overlay mix
    float thres = 0.7;
    if (lum < thres)
        col = hue * lum / thres;
    else
        col = vec3(1.0) - (vec3(1.0 - (lum - thres)) * (vec3(1.0) - hue));


    // Output to screen
    fragColor = vec4(col,1.0);
}

// Author: bitless
// Title: Microwaves

// Thanks to Patricio Gonzalez Vivo & Jen Lowe for "The Book of Shaders"
// and Fabrice Neyret (FabriceNeyret2) for https://shadertoyunofficial.wordpress.com/
// and Inigo Quilez (iq) for  https://iquilezles.org/www/index.htm
// and whole Shadertoy community for inspiration.

#define p(t, a, b, c, d) ( a + b*cos( 6.28318*(c*t+d) ) ) //palette function (https://iquilezles.org/articles/palettes)
#define S(x,y,z) smoothstep(x,y,z)

float w(float x, float p){ //sin wave function
    x *= 5.;
    float t= p*.5+sin(iTime*.25)*10.5;
    return (sin(x*.25 + t)*5. + sin(x*4.5 + t*3.)*.2 + sin(x + t*3.)*2.3  + sin(x*.8 + t*1.1)*2.5)*0.275;
}



void mainImage( out vec4 fragColor, in vec2 g)
{
    vec2 r = iResolution.xy
        ,st = (g+g-r)/r.y;

    float 	th = .05 //thickness
    		,sm = 15./r.y+.85*length(S(vec2(01.,.2),vec2(2.,.7),abs(st))) //smoothing factor
    		,c = 0. 
            ,t = iTime*0.25
            ,n = floor((st.y+t)/.1)
            ,y = fract((st.y+t)/.1);

    vec3 clr;
    for (float i = -5.;i<5.;i++)
    {
        float f = w(st.x,(n-i))-y-i;
        c = mix(c,0.,S(-0.3,abs(st.y),f));
        c += S(th+sm,th-sm,abs(f))
            *(1.-abs(st.y)*.75)
            + S(5.5-abs(f*0.5),0.,f)*0.25;

        clr = mix(clr,p(sin((n-i)*.15),vec3(.5),vec3(.5), vec3(.270), vec3(.0,.05,0.15))*c,S(-0.3,abs(st.y),f));
    }
    fragColor = vec4(clr,1.);
}

float v(in vec2 uv, float d, float o){
    return 1.0-smoothstep(0.0, d, distance(uv.x, 0.5 + sin(o+uv.y*3.0)*0.3));
}

vec4 b(vec2 uv, float o) {
 float d = 0.05+abs(sin(o*0.2))*0.25 * distance(uv.y+0.5, 0.0);
 return vec4(v(uv+vec2(d*0.25, 0.0), d, o), 0.0, 0.0, 1.0) +
        vec4(0.0, v(uv-vec2(0.015, 0.005), d, o), 0.0, 1.0) + 
        vec4(0.0, 0.0, v(uv-vec2(d*0.5, 0.015), d, o), 1.0);   
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
	vec2 uv = fragCoord.xy / iResolution.y;
	fragColor =  b(uv, iTime)*0.5 + 
       b(uv, iTime*2.0)*0.5 + 
       b(uv+vec2(0.3, 0.0), iTime*3.3)*0.5;


}

#define E 0
#define O 1
#define R 2

float get_sd_line(vec2 p, vec2 a, vec2 b, float r) {
    vec2 ab = b - a;
    vec2 ap = p - a;
    float t = clamp(dot(ap, ab) / dot(ab, ab), 0.0, 1.0);
    return length(a + t * ab - p) - r;
}

float smin(float a, float b, float k) {
    k *= 4.0;
    float h = max(k - abs(a - b), 0.0) / k;
    return min(a, b) - h * h * k * (1.0 / 4.0);
}

float smin(float a, float b) {
    float sd = smin(a, b, 0.01);
    return sd;
}

float get_sd_E(vec2 p, float r) {
    vec2 a = vec2(-0.3, -0.5);
    vec2 b = vec2(-0.3, 0.5);
    vec2 c = vec2(0.3, 0.5);
    vec2 d = vec2(0.3, 0.3);
    vec2 e = vec2(-0.3, 0.0);
    vec2 f = vec2(0.2, 0.0);
    vec2 g = vec2(0.3, -0.5);

    float sd = get_sd_line(p, a, b, r);
    sd = smin(sd, get_sd_line(p, b, c, r));
    sd = smin(sd, get_sd_line(p, e, f, r));
    sd = smin(sd, get_sd_line(p, a, g, r));

    return sd;
}

float get_sd_R(vec2 p, float r) {
    vec2 a = vec2(-0.3, -0.5);
    vec2 b = vec2(-0.3, 0.5);
    vec2 c = vec2(0.3, 0.5);
    vec2 d = vec2(0.3, 0.0);
    vec2 e = vec2(-0.1, 0.0);
    vec2 f = vec2(0.3, -0.5);

    float sd = get_sd_line(p, a, b, r);
    sd = smin(sd, get_sd_line(p, b, c, r));
    sd = smin(sd, get_sd_line(p, c, d, r));
    sd = smin(sd, get_sd_line(p, d, e, r));
    sd = smin(sd, get_sd_line(p, e, f, r));

    return sd;
}

float get_sd_O(vec2 p, float r) {
    vec2 a = vec2(-0.3, -0.5);
    vec2 b = vec2(-0.3, 0.5);
    vec2 c = vec2(0.3, 0.5);
    vec2 d = vec2(0.3, -0.5);

    float sd = get_sd_line(p, a, b, r);
    sd = smin(sd, get_sd_line(p, b, c, r));
    sd = smin(sd, get_sd_line(p, c, d, r));
    sd = smin(sd, get_sd_line(p, d, a, r));

    return sd;
}

float get_sd_letter(vec2 p, int letter_idx, float r) {
    switch (letter_idx) {
        case E:
        return get_sd_E(p, r);
        case R:
        return get_sd_R(p, r);
        case O:
        return get_sd_O(p, r);
        default:
        return 10e6;
    }
}

void type_letter(inout vec2 cursor, inout float sd, int letter_idx, float r) {
    cursor.x -= 1.0;
    sd = smin(sd, get_sd_letter(cursor, letter_idx, r));
}

float attenuate(float x, float a, float b, float c) {
    return 1.0 / (a + b * x + c * x * x);
}

float get_brightness(vec2 p) {
    float x = p.x + 5.0 * sin(iTime);
    float b = attenuate(x, 0.1, 1.0, 20.0);
    return b;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float aspect = iResolution.x / iResolution.y;

    vec2 p = 5.0 * ((uv * 2.0) - 1.0);
    p.x *= aspect;

    vec2 cursor = p;
    cursor.x += 3.0;

    float r = 0.15;
    float brightness = 0.1 * get_brightness(p);

    float sd = 10e9;
    type_letter(cursor, sd, E, r);
    type_letter(cursor, sd, R, r);
    type_letter(cursor, sd, R, r);
    type_letter(cursor, sd, O, r);
    type_letter(cursor, sd, R, r);

    float t = 1.0 / pow(sin(abs(sd)), 2.5);
    vec3 color = vec3(0.2, 1.0, 0.0);
    color = t * brightness * color;

    fragColor = vec4(color, 1.0);
}

#define t iTime
#define SAMPLES 10
#define FOCAL_DISTANCE 4.0
#define FOCAL_RANGE 6.0
mat2 m(float a){float c=cos(a), s=sin(a);return mat2(c,-s,s,c);}

float map(vec3 p){
    p.xz *= m(t * 0.4);
    p.xy *= m(t * 0.3);
    vec3 q = p * 2.0 + t;
    return length(p + vec3(sin(t * 0.7))) * log(length(p) + 1.0) + sin(q.x + sin(q.z + sin(q.y))) * 0.5 - 1.0;
}

vec3 hslToRgb(vec3 hsl) {
    vec3 rgb = clamp(abs(mod(hsl.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    return hsl.z + hsl.y * (rgb - 0.5) * (1.0 - abs(2.0 * hsl.z - 1.0));
}




vec3 getColor(in vec2 fragCoord, in float depth) {
    vec2 p = fragCoord.xy / iResolution.y - vec2(.9, .5);
    vec3 cl = vec3(0.);
    float d = depth;

    for (int i = 0; i <= 5; i++) {
        vec3 p = vec3(0, 0, 5.0) + normalize(vec3(p, -1.0)) * d;
        float rz = map(p);
        float f = clamp((rz - map(p + .1)) * 0.5, -0.1, 1.0);

        float hue = mod(t * 1.0 + float(i) / 5.0, 1.0);
        vec3 color = hslToRgb(vec3(hue, 1.0, 0.5));

        vec3 l = color + vec3(5.0, 2.5, 3.0) * f;
        cl = cl * l + smoothstep(2.5, 0.0, rz) * 0.7 * l;

        d += min(rz, 1.0);
    }

    return cl;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec3 color = vec3(0.0);
    float depthSum = 0.0;
    float focalFactor = 0.0;

    for (int i = 0; i < SAMPLES; i++) {
        float depth = FOCAL_DISTANCE + (float(i) / float(SAMPLES - 1)) * FOCAL_RANGE;
        vec3 sampleColor = getColor(fragCoord, depth);
        float weight = 1.0 / (1.0 + abs(depth - FOCAL_DISTANCE));

        color += sampleColor * weight;
        depthSum += weight;
    }

    color /= depthSum;

    fragColor = vec4(color, 1.0);
}

/*--------------------------------
  HOLOGRAPHIC OCEAN INSTALLATION
--------------------------------*/

#define PI 3.1415926535897932384626433832795

// WAVE DRAWING FUNCTION
vec4 wave(vec2 uv, float thic, float xoff, float yoff, float freq, float amp, float blur, float speed, vec3 colour) {
    return vec4(
        colour, 
        smoothstep(
            .001 / iResolution.y, 
            -abs(uv.x * blur), 
            abs(yoff + (amp/2. * cos(uv.x * freq * PI + (iTime * speed) + xoff)) - uv.y) - thic)
    );
}

// CIRCLE FUNCTION
vec4 circle(vec2 uv, vec2 pos, float rad, vec3 col, bool edg, float smt) {
    float value = distance(pos, uv);

    if (edg) // Smooth edges mode
        value = smoothstep(value, value + smt, rad);
    else     // Hard edges mode
        value = step(value, rad);

    return vec4(col, value);
}

// ROTATION FUNCTION
mat2 rotate2d(float _angle){
    return mat2(cos(_angle), -sin(_angle),
                sin(_angle), cos(_angle));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Aspect Ratio Fix
    uv = uv * 2. - 1.;
    uv.x *= iResolution.x/iResolution.y;

    // UV Rotation
    uv *= rotate2d(sin(iTime * PI/2.)/10.);

    // Time varying pixel color
    vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // Black background
    vec4 background = vec4(0., 0., 0., 0.);
    vec4 foreground;

    // Draw waves
    int waveCount = 100;
    for(int i = 1; i < waveCount; i++) {
        float j = float(i);

        // Shine layer
        col = 0.5 + 0.5 * cos(iTime + (0.05 * j) + uv.xyx + vec3(0, 2, 4));
        foreground = wave(
            uv, 
            0.005 * (sin(iTime) + 1.5),   // Thickness
            0.05 * j,                     // X Offset
            0.66 - (0.0125 * j),          // Y Offset
            1.0 - (0.02 * j),             // Frequency
            0.25,                         // Amplitude
            0.05,                         // Edge Blur
            2.0,                          // Animation Speed
            vec3(1., 1., 1.)
        );
        background = mix(background, foreground, foreground.a);

        // Floating Ball
        if(i >= (waveCount/2 - 1)) {
            foreground = circle(
                uv,
                vec2(
                    0.,
                    i < waveCount/2 ?
                        0.15 * sin(iTime) - 0.1:
                        0.15 * sin(iTime) - 0.05
                ),
                i > waveCount/2 ?
                    0.45 - (0.02 * (j - float(waveCount)/2.)) :
                    0.4 - (0.02 * (j - float(waveCount)/2.)),
                i < waveCount/2 ?
                    col :
                    vec3(0., 0., 0.),
                i == waveCount/2 ? 
                    false : 
                    true,
                0.1
            );
            background = mix(background, foreground, foreground.a);
        }

        // Colour wave
        foreground = wave(
            uv, 
            0.005 * (sin(iTime)/2. + 1.5),   // Thickness
            0.05 * j,                        // X Offset
            0.65 - (0.0125 * j),             // Y Offset
            1.0 - (0.02 * j),                // Frequency
            0.25,                            // Amplitude
            0.015,                           // Edge Blur
            2.0,                             // Animation Speed
            col
        );
        background = mix(background, foreground, foreground.a);
    }

    // Output to screen
    fragColor = mix(background, foreground, foreground.a);
}

#define PI acos(-1.)

//=========================//
//  Color transformations  //
//=========================//

float g(in float x, in float m, in float t1, in float t2) {
    return exp(-0.5 * pow((x < m ? t1 : t2) * (x - m), 2.));
}

// https://en.wikipedia.org/wiki/CIE_1931_color_space#Analytical_approximation
vec3 wl2xyz(in float w){
    float x = 1.056 * g(w, 599.8, 0.0264, 0.0323) + 0.362 * g(w, 442.0, 0.0624, 0.0374) - 0.065 * g(w, 501.1, 0.049, 0.0382);
    float y = 0.821 * g(w, 568.8, 0.0213, 0.0247) + 0.286 * g(w, 530.9, 0.0613, 0.0322);
    float z = 1.217 * g(w, 437.0, 0.0845, 0.0278) + 0.681 * g(w, 459.0, 0.0385, 0.0725);
    return vec3(x,y,z);
}

// http://www.brucelindbloom.com/index.html?Eqn_RGB_XYZ_Matrix.html
const mat3 XYZ2SRGB = mat3(3.2404542, -1.5371385, -0.4985314,
                           -0.9692660, 1.8760108, 0.0415560,
                           0.0556434, -0.2040259, 1.0572252);

// x = current wavelength
// u = control point wavelength
#define gauss(x, u, o, A) A/o*exp(-0.5*pow((x - u)/o, 2.0))

// by @Tynach (https://www.shadertoy.com/view/MtcfDj)
// Converts from a wavelength to LMS.
// Constructed using multi-peak Gaussian functions generated using Labplot
// and closely fitted to the CIE 2006 2° cone fundamentals created by Stockman & Sharp 2000).
vec3 waveToLms(float wave, vec3 amount) {
	// LMS Gaussian function parameters for each cone type
	const vec3[5] lParams = vec3[](
		vec3(449.682, 21.6622, 2.36612),
		vec3(477.589, 11.0682, 1.39883),
		vec3(532.488, 25.7494, 34.0478),
		vec3(570.2, 5.91487, 0.243387),
		vec3(585.858, 34.98, 77.8669)
	);

	const vec3[5] mParams = vec3[](
		vec3(450.237, 19.5222, 3.33537),
		vec3(479.559, 13.3211, 3.68813),
		vec3(519.924, 17.1502, 9.68484),
		vec3(542.8, 3.27696, 0.105766),
		vec3(552.158, 33.3895, 77.9298)
	);

	const vec3[5] sParams = vec3[](
		vec3(467.661, 8.84562, 5.32073),
		vec3(422.211, 10.2028, 8.58498),
		vec3(443.084, 11.9848, 19.6347),
		vec3(444.863, 1.30608, -0.0330768),
		vec3(460.886, 25.7907, 24.9128)
	);

	// Return the LMS values for the given wavelength
	return vec3(
		// L cone response curve
		gauss(wave, lParams[0].x, lParams[0].y, lParams[0].z) +
		gauss(wave, lParams[1].x, lParams[1].y, lParams[1].z) +
		gauss(wave, lParams[2].x, lParams[2].y, lParams[2].z) +
		gauss(wave, lParams[3].x, lParams[3].y, lParams[3].z) +
		gauss(wave, lParams[4].x, lParams[4].y, lParams[4].z),

		// M cone response curve
		gauss(wave, mParams[0].x, mParams[0].y, mParams[0].z) +
		gauss(wave, mParams[1].x, mParams[1].y, mParams[1].z) +
		gauss(wave, mParams[2].x, mParams[2].y, mParams[2].z) +
		gauss(wave, mParams[3].x, mParams[3].y, mParams[3].z) +
		gauss(wave, mParams[4].x, mParams[4].y, mParams[4].z),

		// S cone response curve
		gauss(wave, sParams[0].x, sParams[0].y, sParams[0].z) +
		gauss(wave, sParams[1].x, sParams[1].y, sParams[1].z) +
		gauss(wave, sParams[2].x, sParams[2].y, sParams[2].z) +
		gauss(wave, sParams[3].x, sParams[3].y, sParams[3].z) +
		gauss(wave, sParams[4].x, sParams[4].y, sParams[4].z)
	)/sqrt(2.0*PI);
}

// https://en.wikipedia.org/wiki/Planck%27s_law
float BlackBody( float w_nm, float t ) {
    float h = 6.6e-34; // Planck constant
    float k = 1.4e-23; // Boltzmann constant
    float c = 3e8;// Speed of light
    float w = w_nm / 1e9;
    float w5 = w*w*w*w*w;
    float o = 2.*h*(c*c) / (w5 * (exp(h*c/(w*k*t)) - 1.0));
    return o;
}

//==========//
//  Noises  //
//==========//

// by @P_Malin (https://www.shadertoy.com/view/lsKczc)
float hash11(float p) {
	vec3 p3  = fract(vec3(p) * .5);
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.x + p3.y) * p3.z);
}

// by @P_Malin (https://www.shadertoy.com/view/lsKczc)
float SmoothNoise(float o) {
	float p = floor(o);
	float f = fract(o);

	float a = hash11(p);
	float b = hash11(p+1.0);

	float f2 = f * f;
	float f3 = f2 * f;

	float t = 3.0 * f2 - 2.0 * f3;

	float res = a + (b-a)*t;

    return res;
}

//================//
//  Ray marching  //
//================//

// https://iquilezles.org/articles/distfunctions2d/
float sdBox( in vec2 p, in vec2 b ) {
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}

// https://iquilezles.org/articles/distfunctions2d/
float sdCircle( vec2 p, float r ) {
    return length(p) - r;
}

mat2 rotateZ(float angle) {
  float c = cos(angle);
  float s = sin(angle);
  return mat2(
    vec2(c, -s),
    vec2(s, c)
  );
}



//=======================================================================================//
//
// Light spectrum
// by Julien Sulpis (https://twitter.com/jsulpis)                   
// https://www.shadertoy.com/view/lctSDf
//
// inspired by:
// P_Malin - Spectral Power Distribution (https://www.shadertoy.com/view/lsKczc)
// Tynach - Color Blindness LMS Curves (https://www.shadertoy.com/view/MtcfDj)
//
//=======================================================================================//

#define L_MIN 380.
#define L_MAX 780.
#define BEAM_LENGTH 2.
#define BEAM_WIDTH .04
#define PADDING_TOP .3
#define PADDING_BOTTOM .55
#define GRAPH_LINE_THICKNESS 1.5

#define PI acos(-1.)

//======================//
//  Choose a mode here  //
//======================//

#define BLACKBODY 1
#define NOISE 2
#define MONOCHROMATIC 3

#define MODE NOISE



float getMonochromaticWavelength() {
    float lmin = L_MIN + 10.;
    float lmax = L_MAX - 60.;
    return mix(lmin, lmax, (sin(iTime/2.) + 1.) / 2.);
}

// by @P_Malin (https://www.shadertoy.com/view/lsKczc)
float FBM(float p, float ps) {
	float f = 0.0;
    float tot = 0.0;
    float a = .2;
    for( int i=0; i<5; i++) {
        f += SmoothNoise(p + iTime) * a;
        p *= 2.0;
        tot += a;
        a *= ps;
    }
    return f / tot;
}

// by @P_Malin (https://www.shadertoy.com/view/lsKczc)
float SPD_BlackBody(float w, float t) {
    return BlackBody( w, t ) / BlackBody( 600.0, t );
}

float SPD_Noise(float w) {
    float n = FBM((w) * 0.005, 0.5);
    return pow(n, 3.) * 40.;
}

float SPD(float l_nm) {
    #if MODE == BLACKBODY
        float blackBodyTemperature = 2000. + 8000. * (sin(iTime) + 1.) / 2.;
        return SPD_BlackBody(l_nm, blackBodyTemperature) / 10.;

    #elif MODE == NOISE
        return SPD_Noise(l_nm) * smoothstep(L_MIN-50., L_MIN+100. , l_nm) * smoothstep(L_MAX+50., L_MAX-100., l_nm);

    #elif MODE == MONOCHROMATIC
        return 1. - step(1., abs(l_nm - getMonochromaticWavelength()));

    #else 
        return 1.;
    #endif
}

float getGraphShape(in float value, in vec2 uv, in bool filled) {
   float v = value - uv.y;
   float graph = smoothstep(0., 1., GRAPH_LINE_THICKNESS - abs(v)/fwidth(v)); // by @FabriceNeyret2 https://www.shadertoy.com/view/lXlGRB

   if (filled) {
       graph += .3 * step(0., uv.y) * (1. - step(value, uv.y));
   }

   graph *= smoothstep(-.1, .15, uv.x) 
          * smoothstep(1.1, .5, uv.x);
   return .9 * graph;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = 2. * (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec3 col = vec3(0.);

    vec2 spectrumUV = vec2(fragCoord.x / iResolution.x * 1.5 - .3, fragCoord.y / iResolution.y * 4. - PADDING_BOTTOM * 2.);
    float w = mix(L_MIN, L_MAX, spectrumUV.x);
    float fPower = SPD(w);     

    if (uv.y < -.1 && uv.y > -1. + PADDING_BOTTOM) {
        #if MODE == MONOCHROMATIC
            col = wl2xyz(w) * .5;
        #else 
            col = wl2xyz(w) * fPower * 2.;
        #endif

    } else if (uv.y > -.1 && abs(uv.x) < 1.) {
        #if MODE == MONOCHROMATIC
            vec3 beamColor =  wl2xyz(getMonochromaticWavelength());
            float beamDist = sdBox(uv, vec2(BEAM_WIDTH/2., 100.));
            beamDist = clamp(beamDist, 0., 1.);
            float beamIntensity = pow(1. - beamDist, 150.) + .2 * pow(1. - beamDist, 40.);
            beamIntensity *= smoothstep(-.5, .5, uv.y);
            col = mix(col, beamColor, beamIntensity);
        #else 
            // radial gradient, inspired by @izutionix: https://www.shadertoy.com/view/wtsyDl (l.31)
            float t = (fragCoord.x/iResolution.x - .5)/(1. - fragCoord.y/iResolution.y - PADDING_TOP * .45) + .45;
            float w = mix(L_MIN, L_MAX, t);
            float fPower = SPD(w);
            col = wl2xyz(w) * fPower * smoothstep(-.3, .5, uv.y);

            // compute the resulting color
            vec3 lightColor = vec3(0.);    
            for(float wl = L_MIN; wl < L_MAX; wl += 5.0) {
                vec3 vCurrXYZ = wl2xyz(wl);
                float fPower = SPD(wl);
                lightColor += vCurrXYZ * fPower;
            }

            // cleaning
            col *= smoothstep(0., .1, 1. - abs(t - .5) ); 
            col *= step(PADDING_TOP, 1. - uv.y);
            col = clamp(col, 0., 1.);

            vec3 beamColor = lightColor / lightColor.y; // normalize lightness

            vec2 p = rotateZ(-PI/5.) * (uv - vec2(.0, 1. - PADDING_TOP));
            float beamDist = sdBox(p, vec2(BEAM_WIDTH/2., 100.));
            beamDist = clamp(beamDist, 0., 1.);
            float beamIntensity = pow(1. - beamDist, 150.) + .2 * pow(1. - beamDist, 40.);
            beamIntensity *= smoothstep(-.7, .7, uv.x + uv.y);
            beamIntensity *= 1. - 0.8 * step(1., 1. - p.y);
            col += beamColor * beamIntensity;

            float gratingDist = sdBox(p, vec2(.15, .001));
            gratingDist = clamp(gratingDist, 0., 1.);
            float gratingIntensity = smoothstep(.008, .0, gratingDist);
            col += vec3(.5) * gratingIntensity;

            float glareDist = sdCircle(p, BEAM_WIDTH/10.);
            glareDist = clamp(glareDist, 0., 1.);
            float glareIntensity = .8 * pow(1. - glareDist, 20.) + .05 * pow(1. - glareDist, 10.);
            col += beamColor * glareIntensity;
        #endif
    }

    #if MODE == MONOCHROMATIC
        float wl = getMonochromaticWavelength();
        vec3 lms = .2 * waveToLms(w, vec3(0.)) * waveToLms(wl, vec3(0.));
        float spdGraph = smoothstep(wl - 1., wl, w) * smoothstep(wl+1., wl, w) * smoothstep(.8, .75, spectrumUV.y) * smoothstep(-.1, -.05, spectrumUV.y);
    #else 
        vec3 lms = waveToLms(w, vec3(0.)) * fPower * 1.2;
        vec2 spdUV = spectrumUV * vec2(1., .25);
        float spdGraph = getGraphShape(fPower, spdUV, false);
    #endif

    col = mix(col, vec3(1.), spdGraph);

    vec2 lmsGraphUV = (spectrumUV + vec2(0., .8)) * vec2(1., .3);
    col = mix(col, vec3(1., .5, 0.), getGraphShape(lms.x, lmsGraphUV, true)); // long - red
    col = mix(col, vec3(0.5, 1., 0.), getGraphShape(lms.y, lmsGraphUV, true)); // medium - green
    col = mix(col, vec3(0.2, 0.3, 1.), getGraphShape(lms.z, lmsGraphUV, true)); // short - blue 


    col = col * XYZ2SRGB;
    col = clamp(col, 0., 1.);

    col = pow(col, vec3(1./2.2));

    fragColor = vec4(col, 1);
}

#define PI 3.1415926535897932384626433832795

float map(float v, float low1, float high1, float low2, float high2) {
	return (v-low1)/(high1-low1)*(high2-low2);
}

vec2 xyzToLonLat(vec3 v) {
    vec3 p = normalize(v);
    float lat = map(asin(p.y), PI*0.5, -PI*0.5, 0.0, 1.0);
    float lon = map(atan(p.x, -p.z), PI, -PI, 0.0, 1.0);
    return vec2(lon, lat);
}

vec3 lonLatToXYZ(vec2 lonLat) {
  float lon = map(lonLat.x, 0.0, 1.0, -PI, PI);
  float lat = map(lonLat.y, 0.0, 1.0, -PI*0.5, PI*0.5);
  float x = sin(lat)*sin(lon);
  float y = cos(lat);
  float z = sin(lat)*cos(lon);
  return vec3(x,y,z);
}

vec3 xRot(vec3 v, float theta) {
  float x = v.x;
  float y = v.y*cos(theta) - v.z*sin(theta);
  float z = v.y*sin(theta) + v.z*cos(theta);
  return vec3(x,y,z);
}

vec3 yRot(vec3 v, float theta) {
  float x = v.z*sin(theta) + v.x*cos(theta);
  float y = v.y;
  float z = v.z*cos(theta) - v.x*sin(theta);
  return vec3(x,y,z);
}

vec3 zRot(vec3 v, float theta) {
  float x = v.x*cos(theta) - v.y*sin(theta);
  float y = v.x*sin(theta) + v.y*cos(theta);
  float z = v.z;
  return vec3(x,y,z);
}

vec2 equiRemap(vec2 lonLat, vec2 delta) {
    vec3 v = lonLatToXYZ(lonLat);
	v = yRot(v,delta.x);
    v = xRot(v,delta.y);
    return xyzToLonLat(v);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float graticuleSize = 0.05;
    float graticuleWeight = 0.003;
    //line to be visualised

    //normalized lonLat
	vec2 lonLat = fragCoord.xy / iResolution.xy;
    lonLat = equiRemap(lonLat, vec2(iTime*0.2,iTime*0.4));
	fragColor = vec4(lonLat,0.0,1.0);
    vec2 graticuleDist = mod(lonLat + vec2(graticuleWeight*0.5),vec2(graticuleSize));
    if (graticuleDist.x < graticuleWeight || graticuleDist.y < graticuleWeight) {
    	fragColor += vec4(0.5);
    }

    //visualising a rhumb line, x is lon, y is lat
    //normalized over 
    vec2 p0 = vec2(0.0,0.0);
    vec2 p1 = vec2(7.0,1.0);
    float slope = (p1.y-p0.y)/(p1.x-p0.x);
    float theta = atan(p1.y-p0.y,p1.x-p0.x);
    float lineHalfWeight = 0.01*(1.0+cos(theta));
    bool b0 = atan(mod(lonLat.y,slope)-p0.y,lonLat.x-p0.x+lineHalfWeight) < theta;
    bool b1 = atan(mod(lonLat.y,slope)-p0.y,lonLat.x-p0.x-lineHalfWeight) > theta;
    if (b0 && b1 ){
    	fragColor = vec4(0.0, 0.0, 1.0, 1.0);
    }
}

/*
    "Nebula 3" by @XorDev

    Based on my tweet shader:
    https://x.com/XorDev/status/1918766627828515190
*/
void mainImage(out vec4 O, vec2 I)
{
    float t = iTime, i, z, d, s;
    for(O *= i; i++<1e2;
        O+=(cos(s+s-vec4(5,0,1,3))+1.4)/d/z)
    {
        vec3 p = z * normalize(vec3(I+I,0) - iResolution.xyy);
        p.z -= t;
        for(d = 1.; d < 64.; d += d)
            p += .7 * cos(p.yzx*d) / d;
        p.xy *= mat2(cos(z*.2 + vec4(0,11,33,0)));
        z += d = .03+.1*max(s=3.-abs(p.x), -s*.2);
    }
    O = tanh(O*O/4e5);
}

// "Supernova remnant" by Duke
// https://www.shadertoy.com/view/MdKXzc
//-------------------------------------------------------------------------------------
// Based on "Dusty nebula 4" (https://www.shadertoy.com/view/MsVXWW) 
