// assign color to the media
vec3 computeColor( float density, float radius )
{
	// color based on density alone, gives impression of occlusion within
	// the media
	vec3 result = mix( vec3(1.0,0.9,0.8), vec3(0.4,0.15,0.1), density );

	// color added to the media
	vec3 colCenter = 7.*vec3(0.8,1.0,1.0);
	vec3 colEdge = 1.5*vec3(0.48,0.53,0.5);
	result *= mix( colCenter, colEdge, min( (radius+.05)/.9, 1.15 ) );

	return result;
}

bool RaySphereIntersect(vec3 org, vec3 dir, out float near, out float far)
{
	float b = dot(dir, org);
	float c = dot(org, org) - 8.;
	float delta = b*b - c;
	if( delta < 0.0) 
		return false;
	float deltasqrt = sqrt(delta);
	near = -b - deltasqrt;
	far = -b + deltasqrt;
	return far > 0.0;
}

// Applies the filmic curve from John Hable's presentation
// More details at : http://filmicgames.com/archives/75
vec3 ToneMapFilmicALU(vec3 _color)
{
	_color = max(vec3(0), _color - vec3(0.004));
	_color = (_color * (6.2*_color + vec3(0.5))) / (_color * (6.2 * _color + vec3(1.7)) + vec3(0.06));
	return _color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{  
    const float KEY_1 = 49.5/256.0;
	const float KEY_2 = 50.5/256.0;
	const float KEY_3 = 51.5/256.0;
    float key = 0.0;
    key += 0.7*texture(iChannel1, vec2(KEY_1,0.25)).x;
    key += 0.7*texture(iChannel1, vec2(KEY_2,0.25)).x;
    key += 0.7*texture(iChannel1, vec2(KEY_3,0.25)).x;

	// ro: ray origin
	// rd: direction of the ray
	vec3 rd = normalize(vec3((fragCoord.xy-0.5*iResolution.xy)/iResolution.y, 1.));
	vec3 ro = vec3(0., 0., -6.+key*1.6);

	// ld, td: local, total density 
	// w: weighting factor
	float ld=0., td=0., w=0.;

	// t: length of the ray
	// d: distance function
	float d=1., t=0.;

    const float h = 0.1;

	vec4 sum = vec4(0.0);

    float min_dist=0.0, max_dist=0.0;

    if(RaySphereIntersect(ro, rd, min_dist, max_dist))
    {

	t = min_dist*step(t,min_dist);

	// raymarch loop
	for (int i=0; i<64; i++) 
	{

		vec3 pos = ro + t*rd;

		// Loop break conditions.
	    if(td>0.9 || d<0.1*t || t>10. || sum.a > 0.99 || t>max_dist) break;

        // evaluate distance function
        float d = map(pos);

		// change this string to control density 
		d = max(d,0.0);

        // point light calculations
        vec3 ldst = vec3(0.0)-pos;
        float lDist = max(length(ldst), 0.001);

        // the color of light 
        vec3 lightColor=vec3(1.0,0.5,0.25);

        sum.rgb+=(vec3(0.67,0.75,1.00)/(lDist*lDist*10.)/80.); // star itself
        sum.rgb+=(lightColor/exp(lDist*lDist*lDist*.08)/30.); // bloom

		if (d<h) 
		{
			// compute local density 
			ld = h - d;

            // compute weighting factor 
			w = (1. - td) * ld;

			// accumulate density
			td += w + 1./200.;

			vec4 col = vec4( computeColor(td,lDist), td );

            // emission
            sum += sum.a * vec4(sum.rgb, 0.0) * 0.2;	

			// uniform scale density
			col.a *= 0.2;
			// colour by alpha
			col.rgb *= col.a;
			// alpha blend in contribution
			sum = sum + col*(1.0 - sum.a);  

		}

		td += 1./70.;

        #ifdef DITHERING
        //idea from https://www.shadertoy.com/view/lsj3Dw
        vec2 uv = fragCoord.xy / iResolution.xy;
        uv.y*=120.;
        uv.x*=280.;
        d=abs(d)*(.8+0.08*texture(iChannel2,vec2(uv.y,-uv.x+0.5*sin(4.*iTime+uv.y*4.0))).r);
        #endif 

        // trying to optimize step size near the camera and near the light source
        t += max(d * 0.1 * max(min(length(ldst),length(ro)),1.0), 0.01);

	}

    // simple scattering
	sum *= 1. / exp( ld * 0.2 ) * 0.6;

   	sum = clamp( sum, 0.0, 1.0 );

    sum.xyz = sum.xyz*sum.xyz*(3.0-2.0*sum.xyz);

	}

    #ifdef BACKGROUND
    // stars background
    if (td<.8)
    {
        vec3 stars = vec3(noise(rd*500.0)*0.5+0.5);
        vec3 starbg = vec3(0.0);
        starbg = mix(starbg, vec3(0.8,0.9,1.0), smoothstep(0.99, 1.0, stars)*clamp(dot(vec3(0.0),rd)+0.75,0.0,1.0));
        starbg = clamp(starbg, 0.0, 1.0);
        sum.xyz += starbg; 
    }
	#endif

    #ifdef TONEMAPPING
    fragColor = vec4(ToneMapFilmicALU(sum.xyz*2.2),1.0);
	#else
    fragColor = vec4(sum.xyz,1.0);
	#endif
}

#define COUNT 20.
#define COL_BLACK vec3(23,32,38) / 255.0 

#define SF 1./min(iResolution.x,iResolution.y)
#define SS(l,s) smoothstep(SF,-SF,l-s)
#define hue(h) clamp( abs( fract(h + vec4(3,2,1,0)/3.) * 6. - 3.) -1. , 0., 1.)

// Original noise code from https://www.shadertoy.com/view/4sc3z2
#define MOD3 vec3(.1031,.11369,.13787)

vec3 hash33(vec3 p3)
{
	p3 = fract(p3 * MOD3);
    p3 += dot(p3, p3.yxz+19.19);
    return -1.0 + 2.0 * fract(vec3((p3.x + p3.y)*p3.z, (p3.x+p3.z)*p3.y, (p3.y+p3.z)*p3.x));
}

float simplex_noise(vec3 p)
{
    const float K1 = 0.333333333;
    const float K2 = 0.166666667;

    vec3 i = floor(p + (p.x + p.y + p.z) * K1);
    vec3 d0 = p - (i - (i.x + i.y + i.z) * K2);

    vec3 e = step(vec3(0.0), d0 - d0.yzx);
	vec3 i1 = e * (1.0 - e.zxy);
	vec3 i2 = 1.0 - e.zxy * (1.0 - e);

    vec3 d1 = d0 - (i1 - 1.0 * K2);
    vec3 d2 = d0 - (i2 - 2.0 * K2);
    vec3 d3 = d0 - (1.0 - 3.0 * K2);

    vec4 h = max(0.6 - vec4(dot(d0, d0), dot(d1, d1), dot(d2, d2), dot(d3, d3)), 0.0);
    vec4 n = h * h * h * h * vec4(dot(d0, hash33(i)), dot(d1, hash33(i + i1)), dot(d2, hash33(i + i2)), dot(d3, hash33(i + 1.0)));

    return dot(vec4(31.316), n);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = fragCoord/iResolution.y;

    float m = 0.;
    float t = iTime *.5;
    vec3 col;
    for(float i=COUNT; i>=0.; i-=1.){
        float edge = simplex_noise(vec3(uv * vec2(2., 0.) + vec2(0, t + i*.15), 1.))*.2 + (.5/COUNT)*i + .25;
        float mi = SS(edge, uv.y) - SS(edge + .005, uv.y);        
        m *= SS(edge, uv.y+.015);
        m += mi;        

        if(mi > 0.){
        	col = hue(i/COUNT).rgb;
        }        
    }           

    col = mix(COL_BLACK, col, m);

    fragColor = vec4(col,1.0);
}

// Simplex 3D Noise
// by Ian McEwan, Stefan Gustavson
vec4 permute(vec4 x) {
    return mod(((x * 34.0) + 1.0) * x, 289.0);
}
vec4 taylorInvSqrt(vec4 r) {
    return 1.79284291400159 - 0.85373472095314 * r;
}

float snoise(vec3 v) {
    const vec2 C = vec2(1.0 / 6.0, 1.0 / 3.0);
    const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);

    vec3 i = floor(v + dot(v, C.yyy));
    vec3 x0 = v - i + dot(i, C.xxx);

    vec3 g = step(x0.yzx, x0.xyz);
    vec3 l = 1.0 - g;
    vec3 i1 = min(g.xyz, l.zxy);
    vec3 i2 = max(g.xyz, l.zxy);

    vec3 x1 = x0 - i1 + C.xxx;
    vec3 x2 = x0 - i2 + C.yyy;
    vec3 x3 = x0 - D.yyy;

    i = mod(i, 289.0);
    vec4 p = permute(permute(permute(
                    i.z + vec4(0.0, i1.z, i2.z, 1.0))
                    + i.y + vec4(0.0, i1.y, i2.y, 1.0))
                + i.x + vec4(0.0, i1.x, i2.x, 1.0));

    float n_ = 1.0 / 7.0;
    vec3 ns = n_ * D.wyz - D.xzx;

    vec4 j = p - 49.0 * floor(p * ns.z * ns.z);

    vec4 x_ = floor(j * ns.z);
    vec4 y_ = floor(j - 7.0 * x_);

    vec4 x = x_ * ns.x + ns.yyyy;
    vec4 y = y_ * ns.x + ns.yyyy;
    vec4 h = 1.0 - abs(x) - abs(y);

    vec4 b0 = vec4(x.xy, y.xy);
    vec4 b1 = vec4(x.zw, y.zw);

    vec4 s0 = floor(b0) * 2.0 + 1.0;
    vec4 s1 = floor(b1) * 2.0 + 1.0;
    vec4 sh = -step(h, vec4(0.0));

    vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
    vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;

    vec3 p0 = vec3(a0.xy, h.x);
    vec3 p1 = vec3(a0.zw, h.y);
    vec3 p2 = vec3(a1.xy, h.z);
    vec3 p3 = vec3(a1.zw, h.w);

    vec4 norm = taylorInvSqrt(vec4(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3)));
    p0 *= norm.x;
    p1 *= norm.y;
    p2 *= norm.z;
    p3 *= norm.w;

    vec4 m = max(0.6 - vec4(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m * m, vec4(dot(p0, x0), dot(p1, x1),
                dot(p2, x2), dot(p3, x3)));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    float aspect = iResolution.x / iResolution.y;

    float zoomout = 2.0;
    vec2 sp = (uv * 2.0 - 1.0) * zoomout;
    sp.x *= aspect;

    vec3 color = vec3(0.0);

    // Grid
    vec2 uv_cell = fract(sp);
    vec2 sp_cell = uv_cell * 2.0 - 1.0;
    vec2 lines = 1.0 - smoothstep(0.0, 0.005, 1.0 - abs(sp_cell) - 0.01);
    float line = max(lines.x, lines.y);
    color += line * 0.1;

    // Line
    float x = sp.x;
    float t = iTime;

    float noise_xt = snoise(vec3(x, t, 0.0));
    float noise_xty = snoise(vec3(x, t, sp.y));

    float signal = sin(x * 3.141592) / (1.0 + pow(0.35 * abs(x), 16.0)) + 0.1 * noise_xt;
    float signal_ratio = clamp(pow(abs(sp.x), 1.0), 0.0, 1.0);
    float y = signal_ratio * signal + (1.0 - signal_ratio) * noise_xty;

    float line_brightness = 0.1 * (15.0 - 10.0 * 2.0 * (noise_xty - 0.5));
    vec3 line_attenuation = vec3(1.0, 160.0, 160.0);

    vec3 signal_color = vec3(0.1, 1.0, 0.0);
    vec3 noise_color = 10.0 * vec3(1.0, 0.3, 0.0);
    vec3 line_color = signal_ratio * signal_color + (1.0 - signal_ratio) * noise_color;

    float d = distance(sp, vec2(x, y));
    float line_intensity = line_brightness / dot(line_attenuation, vec3(1.0, d, d * d));

    color += line_intensity * line_color;

    fragColor = vec4(color, 1.0);
}

// Radiant Furnace — Shadertoy First Edition
// Adapted from the Fractals "sceneGridHymn" family.
// Built as a hotter, denser sibling to Harmonic Grid.

#define PI  3.141592653589793
#define TAU 6.283185307179586

mat2 rot(float a) {
    float s = sin(a);
    float c = cos(a);
    return mat2(c, -s, s, c);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p = p * 2.03 + vec2(7.13, 3.71);
        a *= 0.5;
    }
    return v;
}

vec2 aspectUv(vec2 fragCoord, float zoom) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
    return p * zoom;
}

vec3 furnacePalette(float t) {
    t = clamp(t, 0.0, 1.0);

    vec3 deep   = vec3(0.03, 0.01, 0.005);
    vec3 ember  = vec3(0.32, 0.06, 0.01);
    vec3 fire   = vec3(0.90, 0.32, 0.03);
    vec3 gold   = vec3(1.00, 0.78, 0.24);
    vec3 whiteH = vec3(1.00, 0.96, 0.82);

    vec3 col = mix(deep, ember, smoothstep(0.00, 0.22, t));
    col = mix(col, fire, smoothstep(0.18, 0.55, t));
    col = mix(col, gold, smoothstep(0.48, 0.82, t));
    col = mix(col, whiteH, smoothstep(0.82, 1.00, t));
    return col;
}

vec3 sceneRadiantFurnace(vec2 fragCoord, float time) {
    // Radiant Furnace family index = 36 in your registry.
    // sceneGridHymn uses local = mod(family, 5.0), so local = 1.0 here.
    float local   = 1.0;
    float variant = 6.0;

    vec2 p = aspectUv(fragCoord, 1.22 + local * 0.10 + variant * 0.04);
    p *= rot(time * (0.02 + local * 0.008));

    float gridScale = 2.6 + local * 0.45 + variant * 0.12;
    vec2 gp = abs(fract(p * gridScale) - 0.5);

    float lineCore = min(gp.x, gp.y);
    float lines = exp(-16.0 * lineCore * (1.0 + local * 0.12));

    float waves  = sin((p.x + p.y) * (6.0 + local * 1.6) + time * (1.0 + variant * 0.10));
    float pulses = sin(length(p) * (10.0 + local * 2.4) - time * (1.7 + local * 0.10));
    float mist   = fbm(p * (2.0 + local * 0.35));

    float radialHeat = exp(-1.8 * length(p));
    float emberNoise = fbm(p * 3.2 + vec2(time * 0.06, -time * 0.03));
    float sparks = pow(max(noise(p * 20.0 + time * 0.35) - 0.87, 0.0) * 6.0, 2.0);

    float v = 0.0;
    v += lines * 0.42;
    v += waves * 0.14;
    v += pulses * 0.18;
    v += mist * 0.20;
    v += radialHeat * 0.18;
    v += emberNoise * 0.14;
    v += sparks * 0.08;

    v = clamp(v, 0.0, 1.0);

    float r = length(p);
    float furnaceGlow = smoothstep(1.6, 0.0, r);
    float chamber = 0.65 + 0.35 * furnaceGlow;

    vec3 col = furnacePalette(pow(v, 0.88));
    col *= chamber;

    // Hot line filaments
    col += vec3(1.00, 0.55, 0.12) * pow(lines, 3.0) * 0.12;

    // Interior glow
    col += vec3(1.00, 0.35, 0.05) * radialHeat * 0.10;

    // Spark highlights
    col += vec3(1.00, 0.85, 0.45) * sparks * 0.10;

    // Slight bloom-like shaping
    col *= 0.85 + 0.25 * furnaceGlow;

    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float time = iTime;

    vec3 col = sceneRadiantFurnace(fragCoord, time);

    // Gentle display polish
