float val2 = 1.0- pow(abs(0.45 + sin(fragCoord.y*0.984 + 5.123)*0.05 - uv.y), 1.0) * (ass + 0.4)/(sin(iTime*5.1 - 0.67*x)*0.5+1.0) *32.0;
