#define PI 3.141592

float attenuate(float dist, vec3 coeffs) {
    return 1.0 / (dot(vec3(1.0, dist, dist * dist), coeffs));
}

float get_signal_y(float x, float u_time) {
    float y = sin(x);
    y += 0.5 * sin(2.0 * x - u_time);
    y += 0.25 * sin(4.0 * x);
    y += 0.15 * sin(8.0 * x - u_time);
    y += 0.05 * sin(16.0 * x);
    return y;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float u_aspect = iResolution.x / iResolution.y;
    float u_zoomout = 5.0;
    vec3 u_grid_color = vec3(0.3, 1.0, 0.3);
    vec3 u_signal_color = vec3(0.0, 1.0, 0.0);
    float u_anim_period = 10.0;
    float u_time = iTime + u_anim_period * 0.5;
    float u_distortion = 2.850;
    vec3 u_grid_atten = vec3(1.0, 250.0, 500.0);
    vec3 u_ghost_atten = vec3(1.0, 10.0, 50.0);
    vec3 u_tip_atten = vec3(1.0, 2.0, 4.0);

    vec2 vs_uv = fragCoord / iResolution.xy;
    vec2 sp = vs_uv * 2.0 - 1.0;
    sp.x *= u_aspect;
    sp *= u_zoomout;

    {
        float r = length(sp);
        float power = PI * u_distortion / 100.0;
        sp = normalize(sp) * tan(r * power) / tan(power);
    }

    vec3 signal_color;
    vec2 signal_tip;
    {
        float range = u_zoomout * u_aspect * 2.0;
        range *= 2.0;

        float progress = mod(u_time, u_anim_period) / u_anim_period;

        float tip_x = -0.5 * range + progress * range;
        float tip_y = get_signal_y(tip_x, u_time);
        signal_tip = vec2(tip_x, tip_y);
        float tip_d = distance(sp, signal_tip);

        float ghost_x = sp.x;
        float ghost_y = get_signal_y(ghost_x, u_time);
        float ghost_d = distance(sp, vec2(ghost_x, ghost_y));

        float d = tip_x - sp.x;
        d = d + abs(min(d, 0.0)) * 9999.9;

        vec3 atten = u_ghost_atten;
        atten += pow(d, 2.0);

        float ghost = attenuate(ghost_d, atten);
        ghost += attenuate(tip_d, u_tip_atten);

        signal_color = ghost * u_signal_color;
    }

    vec3 grid_color;
    {
        float dx = min(fract(abs(sp.x)), 1.0 - fract(abs(sp.x)));
        float dy = min(fract(abs(sp.y)), 1.0 - fract(abs(sp.y)));
        float d = min(dx, dy);

        vec3 atten = u_grid_atten;
        atten.x += 0.25 * pow(distance(signal_tip, sp), 2.0);
        float grid = attenuate(d, atten);

        grid_color = grid * u_grid_color;
    }

    vec3 color = grid_color + signal_color;
    fragColor = vec4(color, 1.0);
}

#define S smoothstep

vec4 Line(vec2 uv, float speed, float height, vec3 col) {
    uv.y += S(1., 0., abs(uv.x)) * sin(iTime * speed + uv.x * height) * .2;
    return vec4(S(.06 * S(.2, .9, abs(uv.x)), 0., abs(uv.y) - .004) * col, 1.0) * S(1., .3, abs(uv.x));
}

void mainImage(out vec4 O, in vec2 I) {
    vec2 uv = (I - .5 * iResolution.xy) / iResolution.y;
    O = vec4 (0.);
    for (float i = 0.; i <= 5.; i += 1.) {
        float t = i / 5.;
        O += Line(uv, 1. + t, 4. + t, vec3(.2 + t * .7, .2 + t * .4, 0.3));
    }
}

