    for(float i = 0.; i < 100.; i += 1.0) {
        background = mix(background, foreground, foreground.a);
        foreground = wave(
            uv,
            0.01 + i/10000.,
            0.0,
            0.75 * i/1000. * -sin(iTime),
            i/50.,
            i/150. * cos(iTime),
            i/1000.,
            iTime/1000. * sin(iTime)/10.,
            col
        );
        col = col * 1.025;
    }

    // Circle Cutout
    background = mix(background, foreground, foreground.a);
    foreground = ring(
        uv,
        vec2(0.),
        2.5,
        vec3(0.),
        1.
    );
    background = mix(background, foreground, foreground.a);
    foreground = ring(
        uv,
        vec2(0.),
        0.75,
        vec3(0.),
        -0.5
    );
    background = mix(background, foreground, foreground.a);
    foreground = ring(
        uv,
        vec2(0.),
        0.95,
        vec3(0.),
        -0.5
    );
    background = mix(background, foreground, foreground.a);
    foreground = ring(
        uv,
        vec2(0.),
        0.99,
        vec3(0.),
        -0.5
    );


    // Output to screen
    fragColor = mix(background, foreground, foreground.a);
}

#define pi 3.14159

float thc(float a, float b) {
    return tanh(a * cos(b)) / tanh(a);
}

float ths(float a, float b) {
    return tanh(a * sin(b)) / tanh(a);
}

vec3 pal( in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d )
{
    return a + b*cos( 6.28318*(c*t+d) );
}

float h21 (vec2 a) {
    return fract(sin(dot(a.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

const float num = 32.;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-0.5*iResolution.xy)/iResolution.y;

    float r = 0.35 + 0.13 * thc(3.5, 8. * length(uv) - 1.5 * iTime);
    //float r = 0.35 + 0.13 * thc(3.5, iTime + 10. * h21(uv));
    vec2 p;
    float s = 0.;
    for (float i = 0.; i < num; i++) {
        p = vec2(r * sin(pi * i / num) * cos(i + iTime), -r + 2. * r * i / num);
        vec2 uv2 = uv;

        float d = 4. * length(uv2 - p);
        float R = r * sin(pi * i / num);
        float k = 0.1 + 0. * cos(10. * i + iTime) + 0.2 * R;
        s += smoothstep(-k, k, 0.5 * R * (1. + sin(i + iTime))-d);
        s += step(d, 0.4 * R * (1. + sin(i + iTime))) - step(d, 0.35 * R * (1. + sin(i + iTime)));
        s *= 0.99 * (1. - 0.22 * length(uv));
       // s += 0.28 * max(s,smoothstep(-0.2,0.5, 0.5 * R * (1. + sin(i + iTime))-d));
    }

    vec3 col = vec3(s);
    col = s * pal(s, vec3(1.), vec3(1.), vec3(1.), length(uv) + 0.35 * vec3(0.,0.33,0.66));
    col += vec3(0.025,0.,0.05);
   // Output to screen
    fragColor = vec4(col,1.0);
}

//	Classic Perlin 3D Noise 
//	by Stefan Gustavson
//
vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314 * r;}
vec3 fade(vec3 t) {return t*t*t*(t*(t*6.0-15.0)+10.0);}

float cnoise(vec3 P){
  vec3 Pi0 = floor(P); // Integer part for indexing
  vec3 Pi1 = Pi0 + vec3(1.0); // Integer part + 1
  Pi0 = mod(Pi0, 289.0);
  Pi1 = mod(Pi1, 289.0);
  vec3 Pf0 = fract(P); // Fractional part for interpolation
  vec3 Pf1 = Pf0 - vec3(1.0); // Fractional part - 1.0
  vec4 ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
  vec4 iy = vec4(Pi0.yy, Pi1.yy);
  vec4 iz0 = Pi0.zzzz;
  vec4 iz1 = Pi1.zzzz;

  vec4 ixy = permute(permute(ix) + iy);
  vec4 ixy0 = permute(ixy + iz0);
  vec4 ixy1 = permute(ixy + iz1);

  vec4 gx0 = ixy0 / 7.0;
  vec4 gy0 = fract(floor(gx0) / 7.0) - 0.5;
  gx0 = fract(gx0);
  vec4 gz0 = vec4(0.5) - abs(gx0) - abs(gy0);
  vec4 sz0 = step(gz0, vec4(0.0));
  gx0 -= sz0 * (step(0.0, gx0) - 0.5);
  gy0 -= sz0 * (step(0.0, gy0) - 0.5);

  vec4 gx1 = ixy1 / 7.0;
  vec4 gy1 = fract(floor(gx1) / 7.0) - 0.5;
  gx1 = fract(gx1);
  vec4 gz1 = vec4(0.5) - abs(gx1) - abs(gy1);
  vec4 sz1 = step(gz1, vec4(0.0));
  gx1 -= sz1 * (step(0.0, gx1) - 0.5);
  gy1 -= sz1 * (step(0.0, gy1) - 0.5);

  vec3 g000 = vec3(gx0.x,gy0.x,gz0.x);
  vec3 g100 = vec3(gx0.y,gy0.y,gz0.y);
  vec3 g010 = vec3(gx0.z,gy0.z,gz0.z);
  vec3 g110 = vec3(gx0.w,gy0.w,gz0.w);
  vec3 g001 = vec3(gx1.x,gy1.x,gz1.x);
  vec3 g101 = vec3(gx1.y,gy1.y,gz1.y);
  vec3 g011 = vec3(gx1.z,gy1.z,gz1.z);
  vec3 g111 = vec3(gx1.w,gy1.w,gz1.w);

  vec4 norm0 = taylorInvSqrt(vec4(dot(g000, g000), dot(g010, g010), dot(g100, g100), dot(g110, g110)));
  g000 *= norm0.x;
  g010 *= norm0.y;
  g100 *= norm0.z;
  g110 *= norm0.w;
  vec4 norm1 = taylorInvSqrt(vec4(dot(g001, g001), dot(g011, g011), dot(g101, g101), dot(g111, g111)));
  g001 *= norm1.x;
  g011 *= norm1.y;
  g101 *= norm1.z;
  g111 *= norm1.w;

  float n000 = dot(g000, Pf0);
  float n100 = dot(g100, vec3(Pf1.x, Pf0.yz));
  float n010 = dot(g010, vec3(Pf0.x, Pf1.y, Pf0.z));
  float n110 = dot(g110, vec3(Pf1.xy, Pf0.z));
  float n001 = dot(g001, vec3(Pf0.xy, Pf1.z));
  float n101 = dot(g101, vec3(Pf1.x, Pf0.y, Pf1.z));
  float n011 = dot(g011, vec3(Pf0.x, Pf1.yz));
  float n111 = dot(g111, Pf1);

  vec3 fade_xyz = fade(Pf0);
  vec4 n_z = mix(vec4(n000, n100, n010, n110), vec4(n001, n101, n011, n111), fade_xyz.z);
  vec2 n_yz = mix(n_z.xy, n_z.zw, fade_xyz.y);
  float n_xyz = mix(n_yz.x, n_yz.y, fade_xyz.x); 
  return 2.2 * n_xyz;
}

float plot(vec2 st, float pct){
  float cut = 0.0073;
  return  smoothstep( pct-cut, pct, st.y) -
          smoothstep( pct, pct+cut, st.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv =(fragCoord.xy - 0.5 * iResolution.xy)/iResolution.y; // -.5 <> .5
    vec3 col = vec3(0.);
    for (float i = 0.; i < 30.; i += 1.) {
        float inc = i / 30.;
        float l = plot(
            uv * .5, 0.13 * cnoise(
            vec3(
                smoothstep(0.5, 0., .4 * length(uv)) * 4. + iTime, 
                .2 * iTime + .2 * uv.x,
                -i * 0.02
            )
           ));
        vec3 c = mix(vec3(1., uv.x + .5 - (sin(iTime) * .5), 1. - uv.x), vec3(uv.x + .5, .5 + (sin(uv.x + iTime) * .5), .5 - uv.x), inc);
        col += vec3(l * c * .3);
    }

    // Output to screen
    fragColor = vec4(col,1.);
}

#define T(a) texture(iChannel0,p.xz*.1-t*a)
void mainImage( out vec4 o, in vec2 c ) {
    vec4 p = vec4(c,0.,1.)/iResolution.xyxy-.5, d=p, e;
    float t = iTime+6., x;
    d.y -= .2;
    p.z += t*.3;
    for(float i=1.; i>0.; i-=.02)
    {
        e = sin(p*6.+t);
        x = abs(p.y+e.x*e.z*.1-.75)-(e=T(.01)+T(.02)).x*.08;
        o = .3/length(p.xy+vec2(sin(t),-.4)) - e*i*i;
        if(x<.01) break;
        p -= d*x*.5;
     }
}

#define PI 3.1415
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float i = iTime;
	vec2 uv = fragCoord.xy / iResolution.xy;
    vec4 c = vec4(1.0);
    c.r = sin(uv.y*10.0*cos(uv.x*2.0+i+sin(uv.x+uv.y+i)*tan(uv.y*1.0+i))+i)*.5+.5;
    c.g = sin(c.r*PI*2.0)*.5+.5;
    c.b = sin(c.g*PI*2.0+i)*.5+.5;
	fragColor = c;
}

/*
    "Phosphor 2" by @XorDev

    https://x.com/XorDev/status/1945504914253205515

    <512 playlist:
    https://www.shadertoy.com/playlist/N3SyzR
*/
void mainImage(out vec4 O, vec2 I)
{
    //Animation time
    float t = iTime,
    //Raymarch depth
    z,
    //Step distance
    d,
    //Signed distance
    s,
    //Raymarch iterator
    i;


    //Clear fragColor and raymarch 80 steps
    for(O*=i; i++<8e1;
        //Coloring and brightness
        O+=(cos(s+vec4(0,1,2,0))+1.)/d*z)
    {
        //Sample point (from ray direction)
        vec3 p = z*normalize(vec3(I+I,0)-iResolution.xyy),
        //Rotation axis
        a = normalize(cos(vec3(1,2,0)+t-d*8.));
        //Move camera back 5 units
        p.z+=5.,
        //Rotated coordinates
        a = a*dot(a,p)-cross(a,p);

        //Turbulence loop
        for(d=1.;d++<9.;)
            a+=sin(a*d+t).yzx/d;

        //Distance to ring
        z+=d=.1*abs(length(p)-3.)+.04*abs(s=a.y);
    }
    //Tanh tonemap
    O = tanh(O/3e4);
}

// 'Warp Speed' by David Hoskins 2013.
// I tried to find gaps and variation in the star cloud for a feeling of structure.
// Inspired by Kali: https://www.shadertoy.com/view/ltl3WS

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float time = (iTime+29.) * 60.0;

    float s = 0.0, v = 0.0;
    vec2 uv = (-iResolution.xy + 2.0 * fragCoord ) / iResolution.y;
	float t = time*0.005;
	uv.x += sin(t) * .3;
	float si = sin(t*1.5); // ...Squiffy rotation matrix!
	float co = cos(t);
	uv *= mat2(co, si, -si, co);
	vec3 col = vec3(0.0);
	vec3 init = vec3(0.25, 0.25 + sin(time * 0.001) * .1, time * 0.0008);
	for (int r = 0; r < 100; r++) 
	{
		vec3 p = init + s * vec3(uv, 0.143);
		p.z = mod(p.z, 2.0);
		for (int i=0; i < 10; i++)	p = abs(p * 2.04) / dot(p, p) - 0.75;
		v += length(p * p) * smoothstep(0.0, 0.5, 0.9 - s) * .002;
		// Get a purple and cyan effect by biasing the RGB in different ways...
		col +=  vec3(v * 0.8, 1.1 - s * 0.5, .7 + v * 0.5) * v * 0.013;
		s += .01;
	}
	fragColor = vec4(col, 1.0);
}

