/*
    "Corridor" by @XorDev

    https://x.com/XorDev/status/1923882930834751520
*/
void mainImage(out vec4 O, vec2 I)
{
    //Time for scrolling
    float t = iTime,
    //Raymarch iterator
    i,
    //Raymarch step distance
    d,
    //Raymarch depth
    z;
    //Clear fragColor and raymarch 30 steps
    for(O *= i; i++<3e1;)
    {
        //Compute ray direction 
        vec3 r = normalize(vec3(I+I,0)-iResolution.xyy),
        //Raymarch sample position
        p = z*r,
        //Raytraced wall coordinates
        w = abs(r);
        //Compute distance to walls
        w /= max(w.x,w.y);
        //Scroll forward
        w.z += t;
        p.z -= t;

        //Shift camera
        r = ++p;
        //Step forward
        z += d = length(
        //Reflected coordinates
            (p.xy=abs(mod(p.xy-2.,4.)-2.))-1.
            //Line position
            +cos(p.z/vec2(3.1,2))) +
            //Reflection fall off
            .1 * length(p-r) *
            //Reflectivity blocks
            exp(dot(cos(ceil(w/=.3)),sin(w/.6).yzx));

        //Add coloring
        O.rgb += (cos(p)+1.4) / d / z;
    }
    //Tanh tonemapping
    O = tanh(O/4e1);
}

#define RM_FACTOR   0.9
#define RM_ITERS     90

float plasma(vec3 r) {
	float mx = r.x + iTime / 0.130;
	mx += 20.0 * sin((r.y + mx) / 20.0 + iTime / 0.810);
	float my = r.y - iTime / 0.200;
	my += 30.0 * cos(r.x / 23.0 + iTime / 0.710);
	return r.z - (sin(mx / 7.0) * 2.25 + sin(my / 3.0) * 2.25 + 5.5);
}

float scene(vec3 r) {
	return plasma(r);
}

float raymarch(vec3 pos, vec3 dir) {
	float dist = 0.0;
	float dscene;

	for (int i = 0; i < RM_ITERS; i++) {
		dscene = scene(pos + dist * dir);
		if (abs(dscene) < 0.1)
			break;
		dist += RM_FACTOR * dscene;
	}

	return dist;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
	float c, s;
	float vfov = 3.14159 / 2.3;

	vec3 cam = vec3(0.0, 0.0, 30.0);

	vec2 uv = (fragCoord.xy / iResolution.xy) - 0.5;
	uv.x *= iResolution.x / iResolution.y;
	uv.y *= -1.0;

	vec3 dir = vec3(0.0, 0.0, -1.0);

	float xrot = vfov * length(uv);

	c = cos(xrot);
	s = sin(xrot);
	dir = mat3(1.0, 0.0, 0.0,
	           0.0,   c,  -s,
	           0.0,   s,   c) * dir;

	c = normalize(uv).x;
	s = normalize(uv).y;
	dir = mat3(  c,  -s, 0.0,
	             s,   c, 0.0,
	           0.0, 0.0, 1.0) * dir;

	c = cos(0.7);
	s = sin(0.7);
	dir = mat3(  c, 0.0,   s,
	           0.0, 1.0, 0.0,
	            -s, 0.0,   c) * dir;

	float dist = raymarch(cam, dir);
	vec3 pos = cam + dist * dir;

	fragColor.rgb = mix(
		vec3(0.4, 0.8, 1.0),
		mix(
			vec3(0.0, 0.0, 1.0),
			vec3(1.0, 1.0, 1.0),
			pos.z / 10.0
		),
		1.0 / (dist / 20.0)
	);
}
